import AppKit

/// Volatile, text-only history. Nothing is persisted or sent to Core.
public final class ClipboardHistory {
    public private(set) var items: [String] = []
    public private(set) var enabled = false
    private var lastChange = 0
    private let capacity: Int
    private let maximumBytes: Int
    public static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType", "de.petermaurer.TransientPasteboardType",
        "com.agilebits.onepassword",
    ]
    public static let ignoredSources: Set<String> = ["com.apple.Passwords", "com.apple.keychainaccess"]

    public init(capacity: Int = 50, maximumBytes: Int = 32_768) {
        precondition(capacity > 0 && maximumBytes > 0)
        self.capacity = capacity
        self.maximumBytes = maximumBytes
    }

    public func setEnabled(_ value: Bool, changeCount: Int) {
        enabled = value
        lastChange = changeCount // Never ingest the pre-opt-in clipboard.
        if !value { items.removeAll() }
    }

    public func observe(changeCount: Int, types: Set<String>, source: String?, readText: () -> String?) {
        guard enabled, changeCount != lastChange else { return }
        lastChange = changeCount
        guard types.isDisjoint(with: Self.ignoredTypes),
              !Self.ignoredSources.contains(source ?? ""),
              let text = readText(), !text.isEmpty,
              text.utf8.count <= maximumBytes else { return }
        items.removeAll { $0 == text }
        items.insert(text, at: 0)
        if items.count > capacity { items.removeLast(items.count - capacity) }
    }
}

public final class ClipboardWatcher {
    public let history = ClipboardHistory()
    public var onChange: (() -> Void)?
    private let pasteboard: NSPasteboard
    private var timer: Timer?

    public init(pasteboard: NSPasteboard = .general) { self.pasteboard = pasteboard }
    deinit { timer?.invalidate() }

    public func setEnabled(_ enabled: Bool) {
        timer?.invalidate()
        timer = nil
        history.setEnabled(enabled, changeCount: pasteboard.changeCount)
        if enabled {
            timer = Timer.scheduledTimer(withTimeInterval: 0.5, repeats: true) { [weak self] _ in self?.poll() }
        }
        onChange?()
    }

    public func poll() {
        guard history.enabled else { return }
        let change = pasteboard.changeCount
        let items = pasteboard.pasteboardItems ?? []
        // A concealed marker on ANY item excludes the entire copy.
        let types = Set((pasteboard.types ?? []).map(\.rawValue) + items.flatMap { $0.types.map(\.rawValue) })
        let before = history.items
        let source = pasteboard.string(forType: .init("org.nspasteboard.source"))
        history.observe(changeCount: change, types: types, source: source) {
            // A clipboard replacement during the read must never mix metadata and content.
            guard self.pasteboard.changeCount == change else { return nil }
            let text = self.pasteboard.string(forType: .string)
            guard self.pasteboard.changeCount == change else { return nil }
            return text
        }
        if history.items != before { onChange?() }
    }
}
